/*
 * ФАЙЛ ИГРЫ, НЕ МОДУЛЯ — прокладка ТехноМагии для общего модуля stels-ii.
 * =========================================================
 * Лежит в папке вендора рядом с файлами модуля только потому, что
 * vision.js, alarm.js и light.js модуля импортируют `./tuning.js` из
 * своей папки (MANIFEST.json → needs: ALARM, GUARD, LIGHT). В MANIFEST.json
 * не входит и sha-сверкой не охраняется — правится здесь, как любой файл
 * игры. tools/obnovit-stels-ii.sh при смене версии модуля переносит его в
 * папку новой версии байт в байт.
 *
 * ПРОКЛАДКА: числа МГС для vision.js, alarm.js и light.js модуля
 * =========================================================
 * В МГС это его общий файл настроек
 * (~/dev/_games/stealth/src/tuning.js). Здесь не копия того файла, а
 * ровно те числа, которые перенесённые файлы и наши порты (монета)
 * читают, и ничего сверх: GUARD, LIGHT, ALARM, COIN, NOISE. Коробка,
 * следы, пистолет и позы из МГС сюда не поехали.
 *
 * ПЕРЕВОД МАСШТАБА. Тайл МГС — 24 пикселя, наш — 32. Всё, что в МГС
 * измерено в пикселях (дальность взгляда, чутьё спиной), умножается на
 * 32/24 = 4/3: страж видит столько же КЛЕТОК, сколько видел бы у себя.
 * Углы, секунды и доли не зависят от тайла и переезжают как есть.
 *
 *   величина         МГС        здесь      что это
 *   sight            172 px     229.3 px   ≈7.2 клетки взгляда
 *   half             0.48 рад   0.48       половина конуса, 55° целиком
 *   feel             26 px      34.7 px    ≈1.1 клетки «чует спиной»
 *   notice           0.42 с     0.42       узнавание на пределе дальности
 *   noticeNear       0.3        0.3        доля времени у самого носа
 *   memory           1.3 с      1.3        потерял — столько помнит
 *   scanTurn         0.85 рад   0.85       размах осмотра на месте
 *   turnRate         3.4 рад/с  3.4        195°/с поворота головы
 *   grassSight       0.32       0.32       трава (у нас её нет — не
 *                                          используется, но vision.js
 *                                          её читает, и пустым быть не
 *                                          должно)
 *
 * СВЕТ (с 03.10, слой «б»). light.js МГС переехал дословно, и LIGHT
 * здесь — все его числа: ночь `ambient` 0, ядро пятна `core` 1.35,
 * пороги прибора видимости `hidden`/`bright`, срок `relight` у
 * погашенного рубильником. Все они доли и секунды — от тайла не зависят и
 * едут как есть. Радиусы ламп — пиксели, их ×4/3 считает тот, кто лампу
 * ставит (src/lestnica.js, LAMPS; огонь и свеча — src/vospriyatie/svet.js).
 * На этажах без света (всё, кроме «Башни») у цели нет поля `lit`, и
 * vision.js считает её освещённой целиком — как раньше.
 *
 * МОНЕТА И ШУМЫ (слой «б»). COIN и NOISE — числа МГС
 * (stealth/src/tuning.js: COIN, NOISE.coin), пиксели ×4/3, секунды как
 * есть. Логика полёта и падения — src/vospriyatie/moneta.js.
 */

const SCALE = 32 / 24;

export const GUARD = {
  sight: 172 * SCALE,
  half: 0.48,
  feel: 26 * SCALE,
  notice: 0.42,
  noticeNear: 0.3,
  memory: 1.3,
  scanTurn: 0.85,
  turnRate: 3.4,
  grassSight: 0.32,
};

export const LIGHT = {
  ambient: 0,
  darkSight: 0.15,
  feelDark: 0.45,
  hidden: 0.22,
  bright: 0.6,
  core: 1.35,
  relight: 9,
};

/* Монетка МГС: три штуки, полёт 250 px/с на 152 px. У нас ×4/3. */
export const COIN = { count: 3, speed: 250 * SCALE, range: 152 * SCALE };

/* Шумы МГС, которые слышат наши стражи. Радиусы ×4/3: монета 130 → 173 px,
   то есть те же 5.4 клетки, что в МГС. */
export const NOISE = { coin: 130 * SCALE };

export const ALARM = {
  searchTime: 20,
  cautionTime: 45,
  cautionSight: 1.15,
  cautionSpeed: 1.25,
};

/* Сколько страж проверяет место шума, прежде чем вернуться на пост
   (МГС, NOISE.investigate). Читает его наш ai.js, а не перенесённые
   файлы, — но число из того же источника и живёт рядом с остальными. */
export const INVESTIGATE = 2.8;
